#!/usr/bin/env python3
"""Bind actual final wide layers to the canonical master, without guessing joins."""
from pathlib import Path
import argparse,json
import pyarrow.parquet as pq
H=Path(__file__).resolve().parent;N=H.parent;B=N.parent
def main():
 p=argparse.ArgumentParser();p.add_argument('--master',type=Path,default=N/'core/feature_master.parquet');a=p.parse_args();mc=set(pq.ParquetFile(a.master).schema_arrow.names);axiscols=pq.ParquetFile(B/'anchor_research_20261019/data/point_axis.parquet').schema_arrow.names
 result={'status':'ACTUAL_SOURCE_BINDINGS','master_path':str(a.master),'axis_id':'id','master_id':'id','axis_columns':[c for c in axiscols if c!='id'],'source_bindings':[],'object_bindings':[],'coverage_features':[],'coverage_status_bindings':[],'raw_checks':[],'nonnegative_columns':[],'axis_overrides':[],'missing_layer_columns':[]};covered=set(axiscols)
 layers=[('economy','economy/economy_features.parquet','legal_registration_not_physical_service',False),('wb','services/wb_settlement_features.parquet','provider_locations_not_external_service_catchments',False),('wb_name_relaxed','services/wb_name_relaxed_features.parquet','conditional_name_coordinate_identity_not_baseline_or_catchment',False),('agriculture','agriculture/point_municipal_agriculture.parquet','repeated_native_municipal_context_not_settlement_production',True),('places','places/places_settlement_features.parquet','published_place_location_not_verified_attraction',False)]
 for name,relative,meaning,repeated in layers:
  path=N/relative
  if not path.exists():raise FileNotFoundError('Final national layer unavailable: '+str(path))
  cols=pq.ParquetFile(path).schema_arrow.names;mapping={c:c for c in cols if c!='id' and c in mc};result['missing_layer_columns'] += [{'layer':name,'column':c} for c in cols if c!='id' and c not in mc];covered.update(mapping);result['source_bindings'].append({'name':name,'path':str(path.relative_to(B)),'filters':[],'source_keys':['id'],'master_keys':['id'],'columns':mapping,'source_grain':'one_frozen_settlement_UID','master_evidence_meaning':meaning,'missing_policy':'keep_unknown','units':'feature_specific_see_layer_dictionary','source_date':'feature_specific_see_layer_dictionary','replicated_municipal_context_not_additive':repeated})
  result['nonnegative_columns'] += [c for c in mapping if c.endswith(('_legal_entities','_reporting_entities','_locations'))]
 # Direct frozen trajectory fields not included in new economy's exclusion list.
 tp=B/'functional_dynamics_20261019/economy/pinned_calendar/point_witness_trajectories_2011_2025.parquet';tc=pq.ParquetFile(tp).schema_arrow.names;mapping={'econ_native_trajectory_'+c:c for c in tc if 'econ_native_trajectory_'+c in mc and 'econ_native_trajectory_'+c not in covered}
 if mapping:result['source_bindings'].append({'name':'additional_trajectory_fields','path':str(tp.relative_to(B)),'source_keys':['id'],'master_keys':['id'],'columns':mapping,'missing_policy':'keep_unknown','source_grain':'one_frozen_settlement_UID','units':'field_specific','source_date':'2011–2025'});covered.update(mapping)
 result['coverage_features']=[c for c in ['econ_native_2011_legal_entities','econ_native_2021_legal_entities','econ_native_2025_legal_entities','econ_native_2025_direct_consumer_function_diversity','econ_alias_2025_legal_entities','econ_alias_2025_supplemental_legal_entities','econ_native_2021_legal_registered_revenue_thousand_rub','wb_strict_focus_types_locations','wb_coordinate_candidate_focus_types_locations','agri_total_ha_2021','agri_production_nominal_thousand_rub_2021'] if c in mc]
 for label,column in [('native_legal2025','econ_native_2025_legal_entities'),('wb_strict_focus','wb_strict_focus_types_locations')]:
  if column in mc:result['coverage_status_bindings'].append({'name':label,'states':{'positive_witness':[{'column':column,'op':'gt','value':0}],'zero_accepted_witness_unknown_physical_absence':[{'column':column,'op':'eq','value':0}]}})
 for label,column in [('agriculture_identity','agri_municipality_series_matched'),('agriculture_profile2021','agri_profile2021_covered')]:
  if column in mc:result['coverage_status_bindings'].append({'name':label,'states':{'accepted_context':[{'column':column,'op':'eq','value':True}],'unknown_or_unavailable_context':[{'column':column,'op':'eq','value':False}]}})
 result['risk_flags']=[{'kind':c,'severity':'REVIEW_SOURCE_CONFLICT','filters':[{'column':c,'op':'eq','value':True}]} for c in ['agri_profile2021_inconsistent','agri_latest_crop_inconsistent','agri_latest_crop_dominance_tie','econ_alias_2025_endpoint_presence_sensitive_to_alias'] if c in mc]
 if 'wb_strict_all_types_locations' in mc and 'wb_coordinate_candidate_all_types_locations' in mc:
  candidate_only=[{'column':'wb_strict_all_types_locations','op':'eq','value':0},{'column':'wb_coordinate_candidate_all_types_locations','op':'gt','value':0}];result['risk_flags'].append({'kind':'wb_coordinate_candidates_without_accepted_name_identity','severity':'REVIEW_NOT_ERROR','filters':candidate_only});result['coverage_status_bindings'].append({'name':'wb_linkage_quality','states':{'coordinate_candidate_only_not_accepted_identity':candidate_only}})
 for tier in ['strict','coordinate_candidate']:
  col=f'wb_{tier}_all_types_locations'
  if col in mc:result['object_bindings'].append({'name':'wb_'+tier,'path':'national_integration_20261019/services/wb_objects_crosswalk.parquet','object_key':'object_id','source_settlement_key':'wb_strict_uid' if tier=='strict' else 'wb_candidate_uid','master_count_column':col,'accepted_filters':[],'units':'distinct published source objects, not service flows','source_date':'2026-10-19'})
 result['constant_bindings']={'econ_native_quality_mode':'exact_settlement_code_only','econ_native_dataset_revision':json.loads((B/'functional_dynamics_20261019/economy/RFSD_PINNED_DATASET_INFO.json').read_text())['sha'],'econ_native_geography_status':'year_specific_legal_codes_projected_to_frozen2021_settlement_dictionary_not_historical_boundaries'};result['constant_bindings']={k:v for k,v in result['constant_bindings'].items() if k in mc};covered.update(result['constant_bindings']);result['unbound_master_columns']=sorted(mc-covered);(H/'validation_bindings.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');print('Bound',len(covered&mc),'of',len(mc),'columns; unbound',result['unbound_master_columns'])
if __name__=='__main__':main()
